/**
 * Options for the retry helper.
 */
export interface RetryOptions {
  /** Maximum number of attempts (including the first). Default: 3 */
  maxAttempts?: number;
  /** Base delay in milliseconds. Default: 100 */
  baseDelayMs?: number;
  /** Maximum delay in milliseconds (bounds the backoff). Default: 10000 */
  maxDelayMs?: number;
  /** Backoff multiplier. Default: 2 */
  backoffFactor?: number;
  /**
   * Whether to add random jitter to each delay to avoid thundering herds.
   * Default: true
   */
  jitter?: boolean;
  /**
   * Predicate to decide whether an error is retryable.
   * Return false to stop retrying and propagate the error immediately.
   */
  isRetryable?: (error: unknown, attempt: number) => boolean;
  /**
   * Optional callback invoked before each retry delay.
   * Return false to abort the retry loop.
   */
  onBeforeRetry?: (error: unknown, attempt: number) => boolean | Promise<boolean>;
}

/**
 * Error thrown when a retry operation is cancelled before completion.
 */
export class RetryCancelledError extends Error {
  constructor(
    public readonly attempt: number,
    message = 'Retry operation was cancelled'
  ) {
    super(message);
    this.name = 'RetryCancelledError';
  }
}

